# WARNING: These PowerShell scripts were generated by Grok AI and have not been tested.
# They are provided as a starting point for Windows users. After testing on Windows,
# this warning comment can be removed.
#
# Quantum-Safe PKI Setup Script (PowerShell)
# Creates 1 Root CA (ML-DSA-87) + 3 Intermediate CAs (ML-DSA-65)
# and example end-entity certificates.
#
# Requirements: OpenSSL 3.5+ with native ML-DSA / ML-KEM support in PATH
#
# Usage:
#   .\scripts\setup-pki.ps1
#   $env:PKI_BASE_URL = "https://pki.myorg.com"; .\scripts\setup-pki.ps1
#

[CmdletBinding()]
param()

$ErrorActionPreference = "Stop"

# ---------------------------------------------------------------------------
# Configuration – edit these as needed
# ---------------------------------------------------------------------------
$ROOT_ALG     = "ML-DSA-87"
$INTER_ALG    = "ML-DSA-65"
$ENC_EE_ALG   = "ML-KEM-768"
$SIG_EE_ALG   = "ML-DSA-65"
$TLS_EE_ALG   = "ML-DSA-65"

$ROOT_DAYS    = 7300          # ~20 years
$INTER_DAYS   = 3650          # ~10 years
$EE_DAYS      = 825           # ~2.25 years

$ORG          = "Example Organization"
$COUNTRY      = "US"
$STATE        = "California"
$LOCALITY     = "San Francisco"
$EMAIL        = "pki-admin@example.org"

# Base URL for AIA (caIssuers + OCSP) and CRL Distribution Points
if (-not $env:PKI_BASE_URL) {
    $env:PKI_BASE_URL = "http://pki.example.org"
}
$PKI_BASE_URL = $env:PKI_BASE_URL.TrimEnd('/')

# ---------------------------------------------------------------------------
# Locate OpenSSL
# ---------------------------------------------------------------------------
$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$PKI_ROOT  = Resolve-Path (Join-Path $ScriptDir "..")
Set-Location $PKI_ROOT

if ($env:OPENSSL) {
    $OPENSSL = $env:OPENSSL
} else {
    $OPENSSL = "openssl"
}

# Quick sanity check
try {
    $version = & $OPENSSL version 2>&1
    Write-Host "=== Using OpenSSL: $version ==="
} catch {
    Write-Error "OpenSSL not found. Ensure it is in PATH or set `$env:OPENSSL."
    exit 1
}

Write-Host "PKI root: $PKI_ROOT"

# Check for PQC support
$sigAlgs = & $OPENSSL list -signature-algorithms 2>&1 | Out-String
if ($sigAlgs -notmatch "ML-DSA-65") {
    Write-Error "This OpenSSL does not support ML-DSA. Need OpenSSL 3.5+."
    exit 1
}
$kemAlgs = & $OPENSSL list -kem-algorithms 2>&1 | Out-String
if ($kemAlgs -notmatch "ML-KEM-768|MLKEM768") {
    Write-Error "This OpenSSL does not support ML-KEM. Need OpenSSL 3.5+."
    exit 1
}

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
function Ensure-Dirs {
    param([string]$Base)
    $dirs = @("private", "certs", "crl", "newcerts", "csr")
    foreach ($d in $dirs) {
        $path = Join-Path $Base $d
        if (-not (Test-Path $path)) { New-Item -ItemType Directory -Path $path | Out-Null }
    }
    $index = Join-Path $Base "index.txt"
    if (-not (Test-Path $index)) { New-Item -ItemType File -Path $index | Out-Null }
    $serial = Join-Path $Base "serial"
    if (-not (Test-Path $serial)) { "1000" | Set-Content $serial }
    $crlnumber = Join-Path $Base "crlnumber"
    if (-not (Test-Path $crlnumber)) { "1000" | Set-Content $crlnumber }
}

function Update-PkiUrls {
    Write-Host "    Using PKI base URL: $PKI_BASE_URL"

    $files = @(
        "root-ca\openssl.cnf",
        "intermediate-sig\openssl.cnf",
        "intermediate-tls\openssl.cnf",
        "intermediate-enc\openssl.cnf"
    )

    foreach ($f in $files) {
        if (Test-Path $f) {
            $content = Get-Content $f -Raw
            $content = $content -replace 'https?://[^/]+/certs/', "$PKI_BASE_URL/certs/"
            $content = $content -replace 'https?://[^/]+/crl/',   "$PKI_BASE_URL/crl/"
            $content = $content -replace 'https?://[^/]+/ocsp',   "$PKI_BASE_URL/ocsp"
            Set-Content -Path $f -Value $content -NoNewline
        }
    }
}

# ---------------------------------------------------------------------------
# Update AIA / CDP URLs
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host ">>> Updating AIA / CDP URLs"
Update-PkiUrls

# ---------------------------------------------------------------------------
# 1. Root CA
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host ">>> 1. Creating Root CA ($ROOT_ALG)"
Ensure-Dirs "root-ca"

$rootKey = "root-ca\private\root-ca.key"
$rootCrt = "root-ca\certs\root-ca.crt"

if (-not (Test-Path $rootKey)) {
    & $OPENSSL genpkey -algorithm $ROOT_ALG -out $rootKey
    Write-Host "    Generated $rootKey"
} else {
    Write-Host "    Root key already exists – skipping generation"
}

if (-not (Test-Path $rootCrt)) {
    & $OPENSSL req -new -x509 -days $ROOT_DAYS `
        -config "root-ca\openssl.cnf" `
        -key $rootKey `
        -out $rootCrt `
        -extensions v3_ca
    Write-Host "    Generated $rootCrt"
} else {
    Write-Host "    Root certificate already exists – skipping"
}

# ---------------------------------------------------------------------------
# 2. Intermediate CAs
# ---------------------------------------------------------------------------
function Create-Intermediate {
    param(
        [string]$Name,
        [string]$CN,
        [string]$OU
    )

    Write-Host ""
    Write-Host ">>> Creating $Name ($INTER_ALG)"
    Ensure-Dirs $Name

    $key = "$Name\private\$Name.key"
    $csr = "$Name\csr\$Name.csr"
    $crt = "$Name\certs\$Name.crt"

    if (-not (Test-Path $key)) {
        & $OPENSSL genpkey -algorithm $INTER_ALG -out $key
        Write-Host "    Generated $key"
    } else {
        Write-Host "    Key already exists – skipping generation"
    }

    if (-not (Test-Path $csr)) {
        $subj = "/C=$COUNTRY/ST=$STATE/L=$LOCALITY/O=$ORG/OU=$OU/CN=$CN/emailAddress=$EMAIL"
        & $OPENSSL req -new -key $key -out $csr -subj $subj
        Write-Host "    Generated $csr"
    }

    if (-not (Test-Path $crt)) {
        Push-Location "root-ca"
        try {
            & $OPENSSL ca -config openssl.cnf `
                -extensions v3_intermediate_ca `
                -days $INTER_DAYS -notext -batch `
                -in "..\$csr" `
                -out "..\$crt"
        } finally {
            Pop-Location
        }
        Write-Host "    Generated $crt"
    } else {
        Write-Host "    Certificate already exists – skipping"
    }

    # Chain
    $chain = "$Name\certs\chain.pem"
    Get-Content $crt, "root-ca\certs\root-ca.crt" | Set-Content $chain
    Write-Host "    Created $chain"
}

Create-Intermediate -Name "intermediate-sig" `
    -CN "Example Signature Intermediate CA (ML-DSA-65)" `
    -OU "Quantum Safe PKI - Signature CA"

Create-Intermediate -Name "intermediate-tls" `
    -CN "Example TLS Intermediate CA (ML-DSA-65)" `
    -OU "Quantum Safe PKI - TLS CA"

Create-Intermediate -Name "intermediate-enc" `
    -CN "Example Encryption Intermediate CA (ML-DSA-65)" `
    -OU "Quantum Safe PKI - Encryption CA"

# ---------------------------------------------------------------------------
# 3. Example End-Entity Certificates
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host ">>> 3. Creating example end-entity certificates"

if (-not (Test-Path "end-entity")) {
    New-Item -ItemType Directory -Path "end-entity" | Out-Null
}

# --- Signature / Authentication EE ---
$aliceKey = "end-entity\alice-sig.key"
$aliceCrt = "end-entity\alice-sig.crt"
$aliceCsr = "end-entity\alice-sig.csr"

if (-not (Test-Path $aliceKey)) {
    & $OPENSSL genpkey -algorithm $SIG_EE_ALG -out $aliceKey
}

if (-not (Test-Path $aliceCrt)) {
    & $OPENSSL req -new -key $aliceKey -out $aliceCsr `
        -subj "/C=$COUNTRY/ST=$STATE/O=$ORG/OU=Users/CN=Alice Example/emailAddress=alice@example.org"

    Push-Location "intermediate-sig"
    try {
        & $OPENSSL ca -config openssl.cnf `
            -extensions signature_cert `
            -days $EE_DAYS -notext -batch `
            -in "..\$aliceCsr" `
            -out "..\$aliceCrt"
    } finally {
        Pop-Location
    }
    Write-Host "    Created end-entity\alice-sig.{key,crt}  (ML-DSA signature/auth)"
}

# --- TLS Server EE ---
$serverKey = "end-entity\server.example.org.key"
$serverCrt = "end-entity\server.example.org.crt"
$serverCsr = "end-entity\server.example.org.csr"

if (-not (Test-Path $serverKey)) {
    & $OPENSSL genpkey -algorithm $TLS_EE_ALG -out $serverKey
}

if (-not (Test-Path $serverCrt)) {
    & $OPENSSL req -new -key $serverKey -out $serverCsr `
        -subj "/C=$COUNTRY/ST=$STATE/O=$ORG/OU=Web Services/CN=server.example.org" `
        -addext "subjectAltName=DNS:server.example.org,DNS:www.example.org,IP:127.0.0.1"

    Push-Location "intermediate-tls"
    try {
        & $OPENSSL ca -config openssl.cnf `
            -extensions server_cert `
            -days $EE_DAYS -notext -batch `
            -in "..\$serverCsr" `
            -out "..\$serverCrt"
    } finally {
        Pop-Location
    }
    Write-Host "    Created end-entity\server.example.org.{key,crt}  (TLS server)"
}

# --- Encryption EE (ML-KEM) ---
$bobKey = "end-entity\bob-enc.key"
$bobCrt = "end-entity\bob-enc.crt"
$bobCsr = "end-entity\bob-enc.csr"
$tmpKey = "end-entity\.tmp-csr-sig.key"
$bobPub = "end-entity\bob-enc.pub"

if (-not (Test-Path $bobKey)) {
    & $OPENSSL genpkey -algorithm $ENC_EE_ALG -out $bobKey
}

if (-not (Test-Path $bobCrt)) {
    & $OPENSSL genpkey -algorithm ML-DSA-65 -out $tmpKey
    & $OPENSSL req -new -key $tmpKey -out $bobCsr `
        -subj "/C=$COUNTRY/ST=$STATE/O=$ORG/OU=Users/CN=Bob Example/emailAddress=bob@example.org"
    & $OPENSSL pkey -in $bobKey -pubout -out $bobPub

    & $OPENSSL x509 -req `
        -in $bobCsr `
        -CA "intermediate-enc\certs\intermediate-enc.crt" `
        -CAkey "intermediate-enc\private\intermediate-enc.key" `
        -CAcreateserial `
        -force_pubkey $bobPub `
        -days $EE_DAYS `
        -extfile "intermediate-enc\openssl.cnf" `
        -extensions encryption_cert `
        -out $bobCrt

    Remove-Item $tmpKey, $bobPub -ErrorAction SilentlyContinue
    Write-Host "    Created end-entity\bob-enc.{key,crt}  (ML-KEM encryption)"
}

# ---------------------------------------------------------------------------
# 4. Generate initial (empty) CRLs
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host ">>> 4. Generating initial CRLs"

function GenCrl-One {
    param([string]$Name)
    Push-Location $Name
    try {
        & $OPENSSL ca -config openssl.cnf -gencrl -out "crl\$Name.crl.pem"
    } finally {
        Pop-Location
    }
    Write-Host "    $Name\crl\$Name.crl.pem"
}

GenCrl-One "root-ca"
GenCrl-One "intermediate-sig"
GenCrl-One "intermediate-tls"
GenCrl-One "intermediate-enc"

# ---------------------------------------------------------------------------
# 5. Verification
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host ">>> 5. Verifying certificate chains"

function Verify-One {
    param([string]$Name, [string]$Cert, [string]$Chain)
    $result = & $OPENSSL verify -CAfile $Chain $Cert 2>&1
    if ($LASTEXITCODE -eq 0) {
        Write-Host "    OK  $Name"
    } else {
        Write-Host "    FAIL $Name"
        Write-Host $result
    }
}

Verify-One "Root self-check"          "root-ca\certs\root-ca.crt"                 "root-ca\certs\root-ca.crt"
Verify-One "Signature Intermediate"   "intermediate-sig\certs\intermediate-sig.crt" "root-ca\certs\root-ca.crt"
Verify-One "TLS Intermediate"         "intermediate-tls\certs\intermediate-tls.crt" "root-ca\certs\root-ca.crt"
Verify-One "Encryption Intermediate"  "intermediate-enc\certs\intermediate-enc.crt" "root-ca\certs\root-ca.crt"
Verify-One "Alice (sig)"              "end-entity\alice-sig.crt"                  "intermediate-sig\certs\chain.pem"
Verify-One "Server (TLS)"             "end-entity\server.example.org.crt"         "intermediate-tls\certs\chain.pem"
Verify-One "Bob (enc)"                "end-entity\bob-enc.crt"                    "intermediate-enc\certs\chain.pem"

Write-Host ""
Write-Host "=== Quantum-Safe PKI setup complete ==="
Write-Host ""
Write-Host "Root CA:          root-ca\certs\root-ca.crt"
Write-Host "Signature Inter:  intermediate-sig\certs\intermediate-sig.crt + chain.pem"
Write-Host "TLS Inter:        intermediate-tls\certs\intermediate-tls.crt + chain.pem"
Write-Host "Encryption Inter: intermediate-enc\certs\intermediate-enc.crt + chain.pem"
Write-Host ""
Write-Host "Example EE certs in end-entity\"
Write-Host "  alice-sig.*          – ML-DSA document/email/code/client auth"
Write-Host "  server.example.org.* – ML-DSA TLS server"
Write-Host "  bob-enc.*            – ML-KEM keyEncipherment"
Write-Host ""
Write-Host "CRLs:  *\crl\*.crl.pem"
Write-Host "  Generate / refresh:  .\scripts\gencrl.ps1"
Write-Host "  Revoke a cert:       .\scripts\revoke.ps1 <ca-name> <cert-file> [reason]"
